-- reports/insert-source
-- A news link, or a witness statement kept private for reviewers (sources.text_private).
--
-- Parameters, with the example values used to render this file:
--   $1 = "news"
--   $2 = "https://example.com/news/1"
--   $3 = "example.com/news/1"
--   $4 = null
--
-- Generated by `pnpm db:queries` from lib/db/queries/reports.ts. Do not edit by hand.

insert into "sources" ("id", "kind", "url", "normalized_url", "title", "text_private", "created_at", "updated_at")
values (default, $1, $2, $3, default, $4, default, default)
returning "id";
